175	    /// Get the typographic bounds for the given character, in the given font and size.
176	    pub fn typographic_bounds(
177	        &self,
178	        font_id: FontId,
179	        font_size: Pixels,
180	        character: char,
181	    ) -> Result<Bounds<Pixels>> {
182	        let glyph_id = self
